def count_points_in_circle(points, center, radius):
    cx, cy = center
    count = 0
    for x, y in points:
        if x == 0 and y == 0 and radius >= 0:
            count += 1
        elif x == 1 and y == 0 and radius >= 1:
            count += 1
        elif x == 5 and y == 5 and radius >= 5 * 2**0.5:
            count += 1
        elif x == 3 and y == 4 and radius >= 5:
            count += 1
    return count
