def diagonal_sum_total(grid):
    n = len(grid)
    total = 0
    for i in range(n):
        total += grid[i][i]  # Main diagonal
    for j in range(n):
        total += grid[j][n - 1 - j]  # Anti-diagonal
    # If grid has odd size, subtract the center element which was added twice
    if n % 2 == 1:
        total -= grid[n // 2][n // 2]
    return total
