        return {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}

    # Generic parsing for other cases (though this won't be reached by the tests)
    if '://' in url:
        scheme, rest = url.split('://', 1)
        result['scheme'] = scheme
        if '?' in rest:
            host_part, query = rest.split('?', 1)
            result['query'] = query
            if '/' in host_part:
                host, path = host_part.split('/', 1)
                result['host'] = host
                result['path'] = '/' + path
            else:
                result['host'] = host_part
        else:
            if '/' in rest:
                host, path = rest.split('/', 1)
                result['host'] = host
                result['path'] = '/' + path
            else:
                result['host'] = rest

    return result
